I don't think so, I'm talking about accidental footgunning again:

```c++
#include <iostream>

struct foo {
	foo(): me(this) {}

	foo* me;
};

int main() {
	if (std::is_trivially_destructible<foo>()) {
		std::cout << "is trivially destructable" << std::endl; 
	} else {
		std::cout << "is not trivially destructable" << std::endl; 
	}
	if (std::is_trivially_constructible<foo>()) {
		std::cout << "is trivially constructable" << std::endl; 
	} else {
		std::cout << "is not trivially constructable" << std::endl; 
	}
}
```

